using sv_5da6306f63174d58ad07b54ca8ccbd56.Client.Services;

namespace sv_5da6306f63174d58ad07b54ca8ccbd56.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            DateTimeOffset.UtcNow.AddDays(2),
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddDays(-3), "Picked Up", "New York, NY"),
                new(DateTimeOffset.UtcNow.AddDays(-2), "In Transit", "Philadelphia, PA"),
                new(DateTimeOffset.UtcNow.AddDays(-1), "In Transit", "Chicago, IL"),
            }),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "San Francisco, CA",
            DateTimeOffset.UtcNow.AddDays(-1),
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddDays(-5), "Picked Up", "Seattle, WA"),
                new(DateTimeOffset.UtcNow.AddDays(-3), "In Transit", "Portland, OR"),
                new(DateTimeOffset.UtcNow.AddDays(-1), "Delivered", "San Francisco, CA"),
            }),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Out for Delivery",
            "Austin, TX",
            DateTimeOffset.UtcNow,
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddDays(-4), "Picked Up", "Miami, FL"),
                new(DateTimeOffset.UtcNow.AddDays(-2), "In Transit", "Houston, TX"),
                new(DateTimeOffset.UtcNow, "Out for Delivery", "Austin, TX"),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

